import React, { useState, useEffect } from 'react'
import { connect } from 'react-redux'
import moment from 'moment'
import {
  Checkbox,
  Grid,
  FormControlLabel,
  Paper,
  Tooltip,
  makeStyles,
} from '@material-ui/core'
import MaterialTable from 'material-table'
import { Close, InfoOutlined } from '@material-ui/icons'

import JukeboxDialog from '../Jukebox/JukeboxDialog'
import PageHeader from '../PageHeader'
import SongRequestDialog from './SongRequestDialog'
import agent from '../../agent'

import {
  CANCEL_SONG_REQUEST,
  SONGS_PAGE_UNLOADED,
  STUDENT_SONGS_PAGE_LOADED,
  SUBMIT_SONG_REMOVAL_REQUEST,
} from '../../constants/actionTypes'

const useStyles = makeStyles((theme) => ({
  icon: {
    marginLeft: theme.spacing(1),
  },
  paper: {
    paddingLeft: theme.spacing(2),
    marginBottom: theme.spacing(4),
  },
  status: {
    alignItems: 'center',
    display: 'flex',
  },
}))

const mapStateToProps = (state) => ({
  ...state.songs,
  currentUser: state.common.currentUser,
  settings: state.common.settings,
})

const mapDispatchToProps = (dispatch) => ({
  onCancel: (id) =>
    dispatch({
      type: CANCEL_SONG_REQUEST,
      payload: agent.Songs.delete(id),
      snackbar: { message: 'Song request canceled', variant: 'success' },
    }),
  onDelete: (song) =>
    dispatch({
      type: SUBMIT_SONG_REMOVAL_REQUEST,
      payload: agent.Songs.update(song),
      snackbar: {
        message: 'Song removal request submitted',
        variant: 'success',
      },
    }),
  onLoad: () =>
    dispatch({
      type: STUDENT_SONGS_PAGE_LOADED,
      payload: agent.Songs.forStudent(),
    }),
  onUnload: () => dispatch({ type: SONGS_PAGE_UNLOADED }),
})

const StudentSongs = ({
  course,
  courseSongs,
  currentUser,
  onCancel,
  onDelete,
  onLoad,
  onUnload,
  settings,
  userSongs,
}) => {
  const [mySongsOnly, setMySongsOnly] = useState(true)
  const [approvedSongsOnly, setApprovedSongsOnly] = useState(false)
  const [data, setData] = useState([])
  const [columns, setColumns] = useState([])

  const classes = useStyles()

  const allowDelete =
    (settings.songs.removals.enabled &&
      (!settings.prime.enabled || !settings.prime.songRemovalEnabled)) ||
    (settings.prime.enabled &&
      settings.prime.songRemovalEnabled &&
      currentUser.hasPrime)

  const handleMySongsOnlyClick = (event) => {
    setMySongsOnly(event.target.checked)
  }

  const handleApprovedSongsOnlyClick = (event) => {
    setApprovedSongsOnly(event.target.checked)
  }

  const getColumns = () => [
    {
      title: 'Request Date',
      field: 'createdAt',
      editable: 'never',
      render: (rowData, renderType) =>
        renderType === 'row'
          ? rowData.createdAt.format('ddd, MMM D, YYYY')
          : rowData.format('ddd, MMM D, YYYY'),
    },
    { title: 'Song Title', field: 'title' },
    { title: 'Song Artist', field: 'artist' },
    {
      title: 'Purchased by',
      field: 'purchasedBy.name',
      editable: 'never',
      hidden: mySongsOnly,
    },
    {
      title: 'Status',
      field: 'status',
      lookup: {
        approved: 'approved',
        pendingApproval: 'pending approval',
        pendingRemoval: 'pending removal',
        rejected: 'rejected',
        removed: 'removed',
      },
      render: (rowData, renderType) =>
        renderType === 'row' ? (
          <span style={{ alignItems: 'center', display: 'flex' }}>
            {rowData.statusDescription ? (
              <>
                {rowData.status}
                <Tooltip
                  arrow
                  color='primary'
                  enterTouchDelay={0}
                  title={rowData.statusDescription}
                >
                  <InfoOutlined style={{ marginLeft: '8px' }} />
                </Tooltip>
              </>
            ) : (
              rowData.status
            )}
          </span>
        ) : (
          <span>{rowData}</span>
        ),
    },
  ]

  const getMappedData = (source) =>
    source.map((song) => ({
      createdAt: moment(song.createdAt),
      title: song.title,
      artist: song.artist,
      purchasedBy: {
        name:
          settings.songs.requests.allowAnonymous && song.student.anonymousSongs
            ? 'anonymous'
            : `${song.student.firstName} ${song.student.lastName}`,
        id: song.student._id,
      },
      status: song.status,
      statusDescription: song.statusDescription,
      _id: song._id,
    }))

  const filterApprovedOnly = (songs) =>
    songs.filter((song) => song.status === 'approved')

  useEffect(() => {
    onLoad()

    return () => {
      return onUnload()
    }
  }, [])

  useEffect(() => {
    const songs = mySongsOnly ? userSongs : courseSongs
    setColumns(getColumns())
    setData(
      getMappedData(approvedSongsOnly ? filterApprovedOnly(songs) : songs)
    )
  }, [approvedSongsOnly, courseSongs, mySongsOnly, userSongs])

  return (
    <>
      <PageHeader
        title={
          'Songs for ' +
          (mySongsOnly ? currentUser.firstName : 'Period ' + course.period)
        }
      >
        <JukeboxDialog />
        <SongRequestDialog />
      </PageHeader>

      <Paper className={classes.paper}>
        <Grid container spacing={2} className={classes.grid}>
          <Grid item md={6} className={classes.grid}>
            <FormControlLabel
              control={
                <Checkbox
                  checked={mySongsOnly}
                  onChange={handleMySongsOnlyClick}
                  name='mySongsOnly'
                />
              }
              label='show only my songs'
            />
          </Grid>
          <Grid item md={6} className={classes.grid}>
            <FormControlLabel
              control={
                <Checkbox
                  checked={approvedSongsOnly}
                  onChange={handleApprovedSongsOnlyClick}
                  name='approvedSongsOnly'
                />
              }
              label='show approved songs only'
            />
          </Grid>
        </Grid>
      </Paper>

      <MaterialTable
        title='Class Playlist'
        columns={columns}
        data={data}
        localization={{
          body: {
            deleteTooltip: allowDelete
              ? 'Delete song'
              : 'Delete song (Requires Prime Membership)',
            emptyDataSourceMessage:
              'No songs have been added to this class playlist',
            editRow: {
              deleteText: `Delete this song for ${settings.songs.removals.purchaseAmount} points?`,
              saveTooltip: 'Delete song',
            },
          },
        }}
        options={{ actionsColumnIndex: -1, paging: false, toolbar: false }}
        editable={{
          isDeletable: (rowData) =>
            rowData.status === 'approved' && allowDelete,
          isDeleteHidden: () => !settings.songs.removals.enabled,
          onRowDelete: (song) =>
            new Promise((resolve) => {
              onDelete({
                id: song._id,
                status: 'pending removal',
                statusDescription: '',
              })
              resolve()
            }),
        }}
        actions={[
          (rowData) => ({
            hidden:
              rowData.status !== 'pending approval' ||
              rowData.purchasedBy.id !== currentUser._id,
            icon: () => <Close />,
            onClick: (_, rowData) =>
              new Promise((resolve, reject) => {
                const dataDelete = [...data]
                const index = rowData.tableData.id
                dataDelete.splice(index, 1)
                setData([...dataDelete])
                onCancel(rowData._id)
                resolve()
              }),
            tooltip: 'Cancel song request',
          }),
        ]}
      />
    </>
  )
}

export default connect(mapStateToProps, mapDispatchToProps)(StudentSongs)
