import React, { useState } from 'react'
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  FormControlLabel,
  Grid,
  IconButton,
  Slider,
  Switch,
  Tooltip,
  Typography,
} from '@material-ui/core'
import { ExpandMore } from '@material-ui/icons'
import { Chart } from 'react-google-charts'
import { CirclePicker } from 'react-color'
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome'
import { faClipboardCheck, faClone } from '@fortawesome/free-solid-svg-icons'
import html2canvas from 'html2canvas'

const TaskDataChart = ({ course, displayScores, scores, task }) => {
  const [bucketSize, setBucketSize] = useState(1)
  const [color, setColor] = useState('#4caf50')
  const [copied, setCopied] = useState(false)
  const [showLargeAverage, setShowLargeAverage] = useState(true)

  const getAverage = (data) =>
    Math.round(
      (data.reduce((sum, score) => sum + score.value, 0) /
        data.length /
        task.totalPoints || 1) * 100
    )

  const handleColorChange = (color) => {
    setColor(color.hex)
  }

  const handleSliderChange = (_, newValue) => {
    setBucketSize(newValue)
  }

  const handleSwitchChange = (event) => {
    setShowLargeAverage(event.target.checked)
  }

  const handleCopyChart = async (e) => {
    e.stopPropagation()
    try {
      const chartElement = document.getElementById('chart_wrapper')
      if (!chartElement) return

      const canvas = await html2canvas(chartElement)
      canvas.toBlob(async (blob) => {
        await navigator.clipboard.write([
          new window.ClipboardItem({ 'image/png': blob }),
        ])
        setCopied(true)
        setTimeout(() => setCopied(false), 2000)
      })
    } catch (err) {
      console.error('Failed to copy chart:', err)
    }
  }

  const data = [
    ['Student', 'Score'],
    ...scores.map((score) => [
      `${score.student.firstName} ${score.student.lastName}`,
      score.value,
    ]),
  ]

  const options = {
    chartArea: { left: '8%', width: '90%' },
    colors: [color],
    hAxis: { title: 'Score' },
    histogram: {
      bucketSize: bucketSize,
      minValue: 0,
      maxValue: task.totalPoints,
    },
    legend: { position: 'none' },
    title: `Period ${course.period} | ${task.title} | ${getAverage(
      displayScores || scores
    )}% avg.`,
    vAxis: { title: 'Number of Students', minorGridlines: { count: 0 } },
  }

  return (
    <Grid container spacing={2}>
      <Grid item xs={12}>
        <div id='chart_wrapper' style={{ position: 'relative' }}>
          <Chart
            chartType='Histogram'
            data={data}
            height='400px'
            options={options}
            width='100%'
          />
          {showLargeAverage && (
            <div
              style={{
                color,
                border: `4px solid ${color}`,
                borderRadius: '8px',
                fontSize: '2rem',
                padding: '4px 8px',
                position: 'absolute',
                right: '12px',
                top: '12px',
              }}
            >
              <em style={{ fontSize: '1.5rem' }}>average</em>{' '}
              <b>{getAverage(displayScores || scores)}%</b>
            </div>
          )}
        </div>
      </Grid>
      <Grid item xs={12}>
        <Accordion>
          <AccordionSummary expandIcon={<ExpandMore />}>
            <div
              style={{
                alignItems: 'center',
                display: 'flex',
                justifyContent: 'space-between',
                width: '100%',
              }}
            >
              <Typography variant='h6'>Histogram Settings</Typography>
              <Tooltip
                aria-label='Copy chart to clipboard'
                arrow
                title={
                  copied
                    ? 'Chart copied to clipboard'
                    : 'Copy chart to clipboard'
                }
              >
                <IconButton
                  aria-label='Copy chart to clipboard'
                  color='secondary'
                  onClick={handleCopyChart}
                >
                  {copied ? (
                    <FontAwesomeIcon icon={faClipboardCheck} fixedWidth />
                  ) : (
                    <FontAwesomeIcon icon={faClone} fixedWidth />
                  )}
                </IconButton>
              </Tooltip>
            </div>
          </AccordionSummary>
          <AccordionDetails>
            <Grid container spacing={2}>
              <Grid item xs={12}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={showLargeAverage}
                      color='primary'
                      name='showLargeAverage'
                      onChange={handleSwitchChange}
                    />
                  }
                  label={`Average ${showLargeAverage ? 'shown' : 'hidden'}`}
                  labelPlacement='start'
                  style={{ margin: 0 }}
                />
              </Grid>
              <Grid item xs={12}>
                <Typography gutterBottom>Bucket Size</Typography>
                <Slider
                  defaultValue={1}
                  marks
                  min={1}
                  max={task.totalPoints}
                  onChange={handleSliderChange}
                  step={1}
                  valueLabelDisplay='auto'
                />
              </Grid>
              <Grid item xs={12}>
                <Typography gutterBottom>Color</Typography>
                <CirclePicker color={color} onChange={handleColorChange} />
              </Grid>
            </Grid>
          </AccordionDetails>
        </Accordion>
      </Grid>
    </Grid>
  )
}

export default TaskDataChart
